  'auth.googleConfigError': { es: 'Configura VITE_GOOGLE_CLIENT_ID en .env para usar Google', en: 'Set VITE_GOOGLE_CLIENT_ID in .env to use Google', fr: 'Définissez VITE_GOOGLE_CLIENT_ID dans .env pour utiliser Google', ko: 'Google을 사용하려면 .env에 VITE_GOOGLE_CLIENT_ID를 설정하세요.', ja: 'Googleを使用するには、.envでVITE_GOOGLE_CLIENT_IDを設定してください。', zh: '在 .env 中设置 VITE_GOOGLE_CLIENT_ID 以使用 Google 登录', it: 'Imposta VITE_GOOGLE_CLIENT_ID in .env per usare Google', 'pt-BR': 'Configure VITE_GOOGLE_CLIENT_ID no .env para usar o Google', pt: 'Define VITE_GOOGLE_CLIENT_ID no .env para usar o Google', de: 'Setze VITE_GOOGLE_CLIENT_ID in der .env-Datei, um Google zu nutzen', ar: 'قم بتعيين VITE_GOOGLE_CLIENT_ID في ملف .env لاستخدام Google', nl: 'Stel VITE_GOOGLE_CLIENT_ID in in .env om Google te gebruiken', hi: 'Google का उपयोग करने के लिए .env में VITE_GOOGLE_CLIENT_ID सेट करें', pl: 'Ustaw VITE_GOOGLE_CLIENT_ID w .env, aby używać Google', sv: 'Ställ in VITE_GOOGLE_CLIENT_ID i .env för att använda Google', tr: 'Google kullanmak için .env dosyasında VITE_GOOGLE_CLIENT_ID ayarlayın', 'zh-TW': '請在 .env 中設定 VITE_GOOGLE_CLIENT_ID 以使用 Google 登入' },
