  'premium.disclaimer2': { es: 'Cancela cuando quieras. Pago único simulado para propósitos de demostración.', en: 'Cancel anytime. Simulated single payment for demonstration purposes.', fr: 'Annulez à tout moment. Paiement unique simulé à des fins de démonstration.', ko: '언제든지 취소 가능. 데모 목적으로 시뮬레이션된 단일 결제입니다.', ja: 'いつでもキャンセル可能。デモ目的のシミュレーションされた単一支払い。', zh: '随时取消。模拟单次付款，仅用于演示目的。', it: 'Annulla quando vuoi. Pagamento singolo simulato a scopo dimostrativo.', 'pt-BR': 'Cancele quando quiser. Pagamento único simulado para fins de demonstração.', pt: 'Cancela quando quiseres. Pagamento único simulado para fins de demonstração.', de: 'Jederzeit kündbar. Simulierte Einmalzahlung zu Demonstrationszwecken.', ar: 'إلغاء في أي وقت. دفعة واحدة محاكاة لأغراض العرض.', nl: 'Altijd opzegbaar. Gesimuleerde eenmalige betaling voor demonstratiedoeleinden.', hi: 'कभी भी रद्द करें। प्रदर्शन उद्देश्यों के लिए अनुकरण एकल भुगतान।', pl: 'Anuluj w każdej chwili. Symulowana pojedyncza płatność w celach demonstracyjnych.', sv: 'Avbryt när som helst. Simulerad engångsbetalning i demonstrationssyfte.', tr: 'İstediğiniz zaman iptal edin. Tanıtım amaçlı simüle edilmiş tek ödeme.', 'zh-TW': '可隨時取消。一次性模擬付款，僅供演示用途。' },
  'notifications.subtitle': { es: 'Personaliza qué notificaciones quieres recibir.', en: 'Customize which notifications you want to receive.', fr: 'Personnalisez les notifications que vous souhaitez recevoir.', ko: '수신할 알림을 사용자 지정하세요.', ja: '受け取りたい通知をカスタマイズしてください。', zh: '自定义你想接收的通知。', it: 'Personalizza quali notifiche vuoi ricevere.', 'pt-BR': 'Personalize quais notificações deseja receber.', pt: 'Personaliza quais notificações pretendes receber.', de: 'Passe an, welche Benachrichtigungen du erhalten möchtest.', ar: 'خصص الإشعارات التي ترغب في تلقيها.', nl: 'Pas aan welke meldingen je wilt ontvangen.', hi: 'आप कौन सी सूचनाएँ प्राप्त करना चाहते हैं, अनुकूलित करें।', pl: 'Dostosuj, które powiadomienia chcesz otrzymywać.', sv: 'Anpassa vilka aviseringar du vill ta emot.', tr: 'Hangi bildirimleri almak istediğinizi özelleştirin.', 'zh-TW': '自訂你想接收哪些通知。' },
